521	/**
522	 * Context passed to beforeAll extension hooks.
523	 * Called once before the evaluation starts.
524	 */
525	export type BeforeAllExtensionHookContext = {
526	  /** The test suite configuration (mutable) */
527	  suite: TestSuite;
528	};
529	
530	/**
531	 * Context passed to beforeEach extension hooks.
532	 * Called before each test case is evaluated.
533	 */
534	export type BeforeEachExtensionHookContext = {
535	  /** The test case about to be evaluated (mutable) */
536	  test: TestCase;
537	};
538	
539	/**
540	 * Context passed to afterEach extension hooks.
541	 * Called after each test case is evaluated.
542	 */
543	export type AfterEachExtensionHookContext = {
544	  /** The test case that was evaluated */
545	  test: TestCase;
546	  /** The result of the evaluation */
547	  result: EvaluateResult;
548	};
549	
550	/**
551	 * Context passed to afterAll extension hooks.
552	 * Called once after all evaluations complete.
553	 *
554	 * @example
555	 * ```javascript
556	 * // extension.js
557	 * module.exports = {
558	 *   afterAll: async (context) => {
559	 *     console.log(`Eval ${context.evalId} completed`);
560	 *     console.log(`Results: ${context.results.length} tests`);
561	 *     // Send to monitoring, database, etc.
562	 *   }
563	 * };
564	 * ```
565	 */
566	export type AfterAllExtensionHookContext = {
567	  /** The test suite configuration */
568	  suite: TestSuite;
569	  /** All evaluation results as plain data objects */
570	  results: EvaluateResult[];
571	  /** Completed prompts with metrics */
572	  prompts: CompletedPrompt[];
573	  /** Unique identifier for this evaluation run */
574	  evalId: string;
575	  /** The full evaluation configuration */
576	  config: Partial<UnifiedConfig>;
577	};
578	
579	/**
580	 * Maps hook names to their context types.
581	 * Used for type-safe extension hook invocation.
582	 */
583	export type ExtensionHookContextMap = {
584	  beforeAll: BeforeAllExtensionHookContext;
585	  beforeEach: BeforeEachExtensionHookContext;
586	  afterEach: AfterEachExtensionHookContext;
587	  afterAll: AfterAllExtensionHookContext;
588	};
