590	/**
591	 * Runs extension hooks for the given hook name and context. The hook will be called with the context object,
592	 * and can update the context object to persist data into provider calls.
593	 * @param extensions - An array of extension paths, or null.
594	 * @param hookName - The name of the hook to run.
595	 * @param context - The context object to pass to the hook. T depends on the type of the hook.
596	 * @returns A Promise that resolves with one of the following:
597	 *  - The original context object, if no extensions are provided OR if the returned context is not valid.
598	 *  - The updated context object, if the extension hook returns a valid context object. The updated context,
599	 *    if defined, must conform to the type T; otherwise, a validation error is thrown.
600	 */
601	/**
602	 * Valid hook names that can be used to filter which hooks an extension runs for.
603	 * If an extension specifies one of these as its function name (e.g., file://path:beforeAll),
604	 * it will only run for that specific hook and use the NEW calling convention: (context, { hookName }).
605	 * If an extension specifies a custom function name (e.g., file://path:myHandler),
606	 * it will run for ALL hooks and use the LEGACY calling convention: (hookName, context).
607	 */
608	const EXTENSION_HOOK_NAMES = new Set(['beforeAll', 'beforeEach', 'afterEach', 'afterAll']);
609	
610	/**
611	 * Extracts the hook name from an extension path.
612	 * Format: file://path/to/file.js:hookName or file://path/to/file.py:hook_name
613	 * @returns The hook name or undefined if not specified
614	 */
615	export function getExtensionHookName(extension: string): string | undefined {
616	  if (!extension.startsWith('file://')) {
617	    return undefined;
618	  }
619	  const lastColonIndex = extension.lastIndexOf(':');
620	  // Check if colon is part of Windows drive letter (position 8 after file://) or not present
621	  if (lastColonIndex > 8) {
622	    const functionName = extension.slice(lastColonIndex + 1);
623	    // Return undefined for empty strings (e.g., "file://hooks.js:")
624	    return functionName || undefined;
625	  }
626	  return undefined;
627	}
