629	export async function runExtensionHook<HookName extends keyof ExtensionHookContextMap>(
630	  extensions: string[] | null | undefined,
631	  hookName: HookName,
632	  context: ExtensionHookContextMap[HookName],
633	): Promise<ExtensionHookContextMap[HookName]> {
634	  if (!extensions || !Array.isArray(extensions) || extensions.length === 0) {
635	    return context;
636	  }
637	
638	  telemetry.record('feature_used', {
639	    feature: 'extension_hook',
640	  });
641	
642	  logger.debug(`Running ${hookName} hook with ${extensions.length} extension(s)`);
643	
644	  let updatedContext: ExtensionHookContextMap[HookName] = { ...context };
645	
646	  for (const extension of extensions) {
647	    invariant(typeof extension === 'string', 'extension must be a string');
648	
649	    // Only run extensions that match the current hook name.
650	    // Extension format: file://path/to/file.js:functionName
651	    //
652	    // Behavior:
653	    // - If functionName is a known hook name (beforeAll, beforeEach, afterEach, afterAll),
654	    //   only run for that specific hook.
655	    // - If functionName is a custom name (e.g., myHandler, extension_hook),
656	    //   run for ALL hooks (generic handler pattern).
657	    // - If no functionName is specified, run for ALL hooks.
658	    const extensionHookName = getExtensionHookName(extension);
659	    if (
660	      extensionHookName &&
661	      EXTENSION_HOOK_NAMES.has(extensionHookName) &&
662	      extensionHookName !== hookName
663	    ) {
664	      logger.debug(
665	        `Skipping extension ${extension} for hook ${hookName} (extension targets ${extensionHookName} only)`,
666	      );
667	      continue;
668	    }
669	
670	    // Determine calling convention based on function name:
671	    // - Known hook names (beforeAll, etc.) use NEW convention: (context, { hookName })
672	    //   These are hook-specific handlers that don't need hookName passed explicitly.
673	    // - Custom names or no function name use LEGACY convention: (hookName, context)
674	    //   These are generic handlers that need hookName to determine which hook is running.
675	    const useNewCallingConvention =
676	      extensionHookName && EXTENSION_HOOK_NAMES.has(extensionHookName);
677	
678	    logger.debug(
679	      `Running extension ${extension} for hook ${hookName} (${useNewCallingConvention ? 'new' : 'legacy'} convention)`,
680	    );
681	
682	    let extensionReturnValue;
683	    try {
684	      if (useNewCallingConvention) {
685	        // NEW convention: fn(context, { hookName })
686	        extensionReturnValue = await transform(extension, context, { hookName }, false);
687	      } else {
688	        // LEGACY convention: fn(hookName, context) - backwards compatible with pre-v0.102 hooks
689	        extensionReturnValue = await transform(extension, hookName, context, false);
690	      }
691	    } catch (error) {
692	      const errorMessage = error instanceof Error ? error.message : String(error);
693	      const wrappedError = new Error(
694	        `Extension hook "${hookName}" failed for ${extension}: ${errorMessage}`,
695	      );
