 * Merges the value returned by an `afterEach` extension hook into the accumulated context.
 *
 * Only a whitelisted set of fields on `result` may be contributed by an extension:
 *  - `namedScores`: shallow-merged; only finite numeric values are accepted (strings, null,
 *    arrays, objects, NaN, Infinity, and -Infinity are silently filtered out).
 *  - `metadata`: shallow-merged, preserving any existing keys not returned by the extension.
 *  - `response.metadata`: shallow-merged, preserving all other `response` fields (e.g. `output`).
 *
 * The `success`, `score`, and `response.output` fields are never overridable by an extension.
 * If the extension returned no result, the accumulated context is preserved unchanged.
 */
function mergeAfterEachResult(
  accumulated: AfterEachExtensionHookContext,
  returned: Partial<AfterEachExtensionHookContext> | undefined,
): AfterEachExtensionHookContext {
  const returnedResult = returned?.result;
  if (!returnedResult) {
    return accumulated;
  }

  const prevResult = accumulated.result;

  // Shallow-merge namedScores, keeping only finite numeric values from the extension.
  const mergedNamedScores: Record<string, number> = { ...(prevResult.namedScores ?? {}) };
  const returnedNamedScores = returnedResult.namedScores;
  if (returnedNamedScores && typeof returnedNamedScores === 'object') {
    for (const [key, value] of Object.entries(returnedNamedScores)) {
      if (typeof value === 'number' && Number.isFinite(value)) {
        mergedNamedScores[key] = value;
      }
    }
  }

  // Shallow-merge metadata, preserving existing keys.
  const returnedMetadata = returnedResult.metadata;
  const mergedMetadata: Record<string, any> = {
    ...(prevResult.metadata ?? {}),
    ...(returnedMetadata && typeof returnedMetadata === 'object' ? returnedMetadata : {}),
  };

  // Shallow-merge response.metadata, preserving all other response fields (e.g. output).
  const prevResponse = prevResult.response;
  const returnedResponse = returnedResult.response;
  let mergedResponse = prevResponse;
  if (
    returnedResponse &&
    typeof returnedResponse === 'object' &&
    returnedResponse.metadata &&
    typeof returnedResponse.metadata === 'object'
  ) {
    mergedResponse = {
      ...(prevResponse ?? {}),
      metadata: {
        ...(prevResponse?.metadata ?? {}),
        ...returnedResponse.metadata,
      },
    } as EvaluateResult['response'];
  }

  return {
    ...accumulated,
    result: {
      ...prevResult,
      namedScores: mergedNamedScores,
      metadata: mergedMetadata,
      response: mergedResponse,
      // success and score are intentionally not overridable — they come from prevResult.
    },
  };
}

